-- See https://wiki.hypr.land/Configuring/Keywords/

local mainMod = "SUPER"

-- Sets "Windows" key as main modifier

-- NOTE: `terminal`, `fileManager`, `menu`, `browser` below are intentionally
-- NOT `local` — old hyprlang's `$terminal = kitty` etc. (defined in
-- hyprland.conf) were visible here via `source =`, which shares one flat
-- namespace. Lua's `require()` does not share locals across files, so
-- hyprland.lua must set these as plain Lua globals BEFORE requiring this
-- file, or every exec_cmd(...) call below is a nil reference.

hl.bind(mainMod .. " + " .. "q", hl.dsp.window.close())

hl.bind(mainMod .. " + " .. "M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch exit"))

hl.bind(mainMod .. " + " .. "E", hl.dsp.exec_cmd(fileManager))

hl.bind(mainMod .. " + " .. "V", hl.dsp.window.float({ action = "toggle" }))

hl.bind(mainMod .. " + " .. "SPACE", hl.dsp.exec_cmd(menu))

hl.bind(mainMod .. " + " .. "P", hl.dsp.window.pseudo())

-- dwindle

hl.bind(mainMod .. " + " .. "RETURN", hl.dsp.exec_cmd(terminal))

hl.bind(mainMod .. " + " .. "w", hl.dsp.exec_cmd("pkill waybar; waybar"))

hl.bind(mainMod .. " + " .. "b", hl.dsp.exec_cmd(browser))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "x", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/power-menu"))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "t", hl.dsp.exec_cmd(os.getenv("HOME") .. "/Dotfiles/scripts/.local/bin/wallpaper-picker"))

-- Control Center (AGS) — waybar's network/bluetooth icons keep opening iwgtk/blueman-manager directly (see TODO.md), so this is ControlCenter's only trigger.
hl.bind(mainMod .. " + " .. "c", hl.dsp.exec_cmd("ags request -i jjsanchezc-shell toggle-cc"))

-- Move focus with mainMod + arrow keys

hl.bind(mainMod .. " + " .. "h", hl.dsp.focus({ direction = "left" }))

hl.bind(mainMod .. " + " .. "l", hl.dsp.focus({ direction = "right" }))

hl.bind(mainMod .. " + " .. "k", hl.dsp.focus({ direction = "up" }))

hl.bind(mainMod .. " + " .. "j", hl.dsp.focus({ direction = "down" }))

-- Window movement
-- NOTE: hyprconf2lua v1.4.0 emitted these 4 binds with a bare
-- `{ direction = "l" }` table as the dispatcher argument, with no
-- hl.dsp.window.move(...) wrapper at all — the dispatcher call itself was
-- silently dropped. Reconstructed to match the hl.dsp.window.move({...})
-- shape used elsewhere in this same file, and switched "l"/"r"/"u"/"d" to
-- the full-word direction values ("left"/"right"/"up"/"down") to match the
-- convention confirmed for hl.dsp.focus({direction=...}) just above.

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "h", hl.dsp.window.move({ direction = "left" }))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "l", hl.dsp.window.move({ direction = "right" }))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "k", hl.dsp.window.move({ direction = "up" }))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "j", hl.dsp.window.move({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]

hl.bind(mainMod .. " + " .. 1, hl.dsp.focus({ workspace = 1 }))

hl.bind(mainMod .. " + " .. 2, hl.dsp.focus({ workspace = 2 }))

hl.bind(mainMod .. " + " .. 3, hl.dsp.focus({ workspace = 3 }))

hl.bind(mainMod .. " + " .. 4, hl.dsp.focus({ workspace = 4 }))

hl.bind(mainMod .. " + " .. 5, hl.dsp.focus({ workspace = 5 }))

hl.bind(mainMod .. " + " .. 6, hl.dsp.focus({ workspace = 6 }))

