-- Example special workspace (scratchpad)
-- Moved off Super+S/Super+Shift+S 2026-08-09 to make room for screenshots
-- (Super+M was already taken by hyprshutdown/exit, so this went to G instead).

hl.bind(mainMod .. " + " .. "G", hl.dsp.workspace.toggle_special("magic"))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "G", hl.dsp.window.move({ workspace = "special:magic" }))

-- Screenshots

hl.bind(mainMod .. " + " .. "S", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/region-capture"))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "S", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.local/bin/full-capture"))

-- Scroll through existing workspaces with mainMod + scroll

hl.bind(mainMod .. " + " .. "mouse_down", hl.dsp.focus({ workspace = "e+1" }))

hl.bind(mainMod .. " + " .. "mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging

hl.bind(mainMod .. " + " .. "mouse:272", hl.dsp.window.drag(), { mouse = true })

hl.bind(mainMod .. " + " .. "mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind(mainMod .. " + " .. "f", hl.dsp.window.fullscreen())

-- Laptop multimedia keys for volume and LCD brightness

-- NOTE: original used `bindel` (locked + repeat-while-held), but
-- hyprconf2lua v1.4.0 dropped the repeat flag for all 4 of these — added
-- `repeating = true` back so holding the key still repeats.

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })

hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true, repeating = true })

hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true, repeating = true })

hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true, repeating = true })

-- Requires playerctl

hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })

hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })

hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })

hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

-- Asus ROG Specific keys
-- NOTE: hyprconf2lua v1.4.0 emitted these as bare numbers (156, 211, ...).
-- Old hyprlang auto-detected a purely-numeric key string as a raw keycode;
-- hl.bind() does not — confirmed via a nested-Hyprland smoke test, which
-- failed all 10 of these with `Unknown keysym: "156"` etc. Fix: prefix with
-- "code:" per https://wiki.hypr.land/Configuring/Basics/Binds/.

hl.bind("code:156", hl.dsp.exec_cmd("rog-control-center"))

-- ASUS Armory crate key

hl.bind("code:211", hl.dsp.exec_cmd("asusctl profile next"))

-- Fan Profile key switch between power profiles

hl.bind("code:121", hl.dsp.exec_cmd("pamixer -t"))

-- Speaker Mute FN+F1

hl.bind("code:122", hl.dsp.exec_cmd("pamixer -d 5"))

-- Volume lower key

hl.bind("code:123", hl.dsp.exec_cmd("pamixer -i 5"))

-- Volume Higher key

hl.bind("code:256", hl.dsp.exec_cmd("pamixer --default-source -t"))

-- Mic mute key

hl.bind("code:232", hl.dsp.exec_cmd("brightnessctl set 10%-"))

-- Screen brightness down FN+F7

hl.bind("code:233", hl.dsp.exec_cmd("brightnessctl set 10%+"))

-- Screen brightness up FN+F8

hl.bind("code:237", hl.dsp.exec_cmd("brightnessctl -d asus::kbd_backlight set 33%-"))

-- Keyboard brightness down FN+F2

hl.bind("code:238", hl.dsp.exec_cmd("brightnessctl -d asus::kbd_backlight set 33%+"))

-- Keyboard brightness up FN+F3

-- Clipboard history



hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "V", hl.dsp.exec_cmd("cliphist list| rofi -dmenu -p \"\"| cliphist decode| wl-copy"))

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)
